const breedData = await browserjs(tabId, () => {
  // Let's find trait sliders or trait lists
  const traits = [];
  document.querySelectorAll('.breed-trait-group, [class*="trait"], .attribute-list__row, [class*="attribute"]').forEach(el => {
    traits.push(el.innerText.trim());
  });

  // Also get any general text or structured data
  const bodyText = document.body.innerText;

  // Look for Energy Level, Barking Level, Coat Type
  const matches = {};
  ['energy', 'barking', 'coat', 'activity'].forEach(term => {
    const regex = new RegExp(`([^\\n]*${term}[^\\n]*)`, 'gi');
    matches[term] = bodyText.match(regex);
  });

  return { traits: traits.slice(0, 30), matches };
});

