    const selected = tg.querySelector('.breed-trait-score__choice--selected')?.innerText?.trim();
    // get score or range if applicable (like 1 to 5 bars)
    const activeBars = tg.querySelectorAll('.breed-trait-score__bar--active, [class*="bar--selected"], [class*="active"]').length;
    const totalBars = tg.querySelectorAll('[class*="bar"]').length;
    // get labels
    const scoreLabels = Array.from(tg.querySelectorAll('.breed-trait-score__score-label span')).map(s => s.innerText.trim());
    return {
      trait: title,
      selected,
      activeBars: totalBars > 0 ? `${activeBars}/${totalBars}` : undefined,
      scoreLabels,
      fullText: tg.innerText.replace(/\n+/g, ' | ')
    };
  });
});
